window.kbPageData["views/entry/k-0974335ea09aad53"] = {"key":"entry/k-0974335ea09aad53","state":{"route":"entry/k-0974335ea09aad53"},"node":{"id":"k-0974335ea09aad53","mode":"k","title":"混合比重","type":"原理与机制","domain":"统计","reading":"","intro":"","priority":100,"aliases":["混合比重是以分项总体量为权重的加权平均","混合比重是以各组总体量为权重的加权平均","混合比重是以各部分总体量为权重的加权平均"],"qs":["国考 2024 副省级 行测#129","国考 2024 行政执法 行测#124","江苏 2024 A类 行测#125"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":3,"repeatPositions":0,"directorySummary":"合并两部分后，某类量占合计总体量的比重，等于该类量在两部分中各自比重的加权平均，权重为各部分占合计总体量的份额。两部分总体量均为正时，若各自比重不同，混合比重严格介于两者之间，若相同则保持不变。","review":{"definition":"合并两部分后，某类量占合计总体量的比重，等于该类量在两部分中各自比重的加权平均，权重为各部分占合计总体量的份额。两部分总体量均为正时，若各自比重不同，混合比重严格介于两者之间，若相同则保持不变。","explanation":"本题按各部分的储能总能量加权，2022年末累计总能量由2021年末累计总能量和2022年新增总能量组成。因此，只要某类电池在2022年新增电站中的能量占比高于其在2022年末累计电站中的能量占比，就能推出该类电池的年末累计占比较上年末上升。液流电池的新增占比为5.6%，高于累计占比3.7%。磷酸铁锂电池和铅酸/铅碳电池的新增占比分别为86.5%和2.7%，均低于各自的累计占比88.7%和4.0%。新增锂离子电池全部为磷酸铁锂电池，因此三元锂电池的新增占比为0，低于其累计占比0.3%。故仅④符合，选B。","references":[],"evidence":"混合后总体比重居中","disposition":"独立词条","basis":"据原题和解析编释。","title":"混合比重","related":[],"examFocus":{"国考 2024 副省级 行测#129":"用混合比重比较同一类电池在2022年新增投运和当年末累计投运中的能量占比，判断累计占比的变化方向。","国考 2024 行政执法 行测#124":"按储能总能量计算比重，逐类比较2022年新增投运的能量占比与当年末累计投运的能量占比。","江苏 2024 A类 行测#125":"从第一季度和上半年累计的出口占比入手，用混合比重分析两季度出口占比的变化，再比较出口额与进出口总额的环比增速。"}},"readings":[{"origin":"k-0974335ea09aad53","title":"混合比重","qs":["国考 2024 副省级 行测#129"],"definition":"合并两部分后，某类量占合计总体量的比重，等于该类量在两部分中各自比重的加权平均，权重为各部分占合计总体量的份额。两部分总体量均为正时，若各自比重不同，混合比重严格介于两者之间，若相同则保持不变。","explanation":"本题按各部分的储能总能量加权，2022年末累计总能量由2021年末累计总能量和2022年新增总能量组成。因此，只要某类电池在2022年新增电站中的能量占比高于其在2022年末累计电站中的能量占比，就能推出该类电池的年末累计占比较上年末上升。液流电池的新增占比为5.6%，高于累计占比3.7%。磷酸铁锂电池和铅酸/铅碳电池的新增占比分别为86.5%和2.7%，均低于各自的累计占比88.7%和4.0%。新增锂离子电池全部为磷酸铁锂电池，因此三元锂电池的新增占比为0，低于其累计占比0.3%。故仅④符合，选B。","evidence":"混合后总体比重居中","doubt":"","references":[]},{"origin":"k-6143d6f6d89c8e9c","title":"混合比重","qs":["国考 2024 行政执法 行测#124"],"definition":"混合比重是将同一统计口径下的各组部分量相加，再除以各组总体量之和所得的比重，等于以各组总体量为权重计算的加权平均。两组总体量均为正且比重不同时，混合比重严格介于两组比重之间。","explanation":"第124题将2022年末累计投运的电站总能量视为2021年末累计总能量与2022年新增总能量之和。对同一种电池，判断2022年末累计能量占比是否高于2021年末，只需看2022年新增能量占比是否高于2022年末累计占比。液流电池为5.6%对3.7%，符合条件。磷酸铁锂电池为86.5%对88.7%，铅酸/铅碳电池为2.7%对4.0%，新增占比均较低。新增投运的锂离子电池能量全部来自磷酸铁锂电池，三元锂电池新增占比为0，低于其年末累计占比0.3%。因此仅④符合，选B。","evidence":"混合后总体比重居中","doubt":"","references":[]},{"origin":"k-f2ce07c0e4efbe09","title":"混合比重","qs":["江苏 2024 A类 行测#125"],"definition":"将若干组的部分量相加、总体量相加，再用两者相除，得到混合比重。它等于以各组总体量为权重的加权平均，两组总体量均为正且比重不同时，混合比重严格介于两组比重之间。","explanation":"本题上半年的进出口总额由第一、第二季度相加，两季总额均为正。第一季度出口占比为57.8%，低于上半年累计占比58.1%，因此第二季度出口占比必然高于58.1%，也高于第一季度。这个推导确定了B项所需的占比变化方向。","evidence":"混合后居中","doubt":"","references":[]}]},"questions":{"国考 2024 副省级 行测#129":{"paper":"国考 2024 副省级 行测","n":129,"mod":"资料分析","src":["a566fec37e508ca7f975.pdf",27],"asrc":["a475ecf57d968bc14cd6.pdf",40],"card":"3f25741a78ebc430c25a072b","links":[{"id":"k-0974335ea09aad53","role":"直接考查","why":"两部分的总体量均为正且比重不同时，混合比重严格介于两部分比重之间。"}]},"国考 2024 行政执法 行测#124":{"paper":"国考 2024 行政执法 行测","n":124,"mod":"资料分析","src":["dfddc59dc6e7d9da5d71.pdf",26],"asrc":["6493f3a6a55c38431852.pdf",40],"card":"2e074b9c3ef21ffa1d4b704c","links":[{"id":"k-0974335ea09aad53","role":"直接考查","why":"上年累计量和当年新增量均为正且两组占比不同时，合并占比严格介于两者之间。"}]},"江苏 2024 A类 行测#125":{"paper":"江苏 2024 A类 行测","n":125,"mod":"资料分析","src":["f8fec75f67d6d1ba5759.pdf",25],"asrc":["0126a1c8aceee632ea2b.pdf",39],"card":"42d72fb8ab7e341bd19a1b5a","links":[{"id":"k-0974335ea09aad53","role":"解题依据","why":"两个季度进出口总额均为正且单季占比不同时，上半年累计出口占比严格介于两个季度的占比之间。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-0974335ea09aad53":[["国考 2024 副省级 行测#129"],["国考 2024 行政执法 行测#124"],["江苏 2024 A类 行测#125"]]}};
